const existing = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const cls = $('Classify Email').first().json || {};
const mail = $('Gmail Trigger').first().json || {};
const binary = $('Gmail Trigger').first().binary || {};

const year = new Date().getFullYear();
const seq = existing.length + 1;
const applicationId = 'APP-' + year + '-' + String(seq).padStart(6, '0');

const email = (cls.candidate_email || mail.from || '').toString().toLowerCase().trim();
const dupRow = existing.find(r => (r.Email || '').toString().toLowerCase().trim() === email);
const isDuplicate = !!dupRow;
const finalId = isDuplicate ? (dupRow['Candidate ID'] || applicationId) : applicationId;

// Attachment detection
const keys = Object.keys(binary);
let cvKey = null, cvType = 'none', outBinary = {};
for (const k of keys) {
  const b = binary[k] || {};
  const name = (b.fileName || '').toLowerCase();
  const ext = (b.fileExtension || name.split('.').pop() || '').toLowerCase();
  if (['pdf','txt','doc','docx','png','jpg','jpeg'].includes(ext)) {
    cvKey = k;
    if (ext === 'pdf') cvType = 'pdf';
    else if (ext === 'txt') cvType = 'txt';
    else cvType = 'other';
    outBinary = { data: b };
    break;
  }
}
const hasCv = cvKey !== null;

const appliedPosition = cls.job_position || (dupRow && dupRow.Position) || '';
const differentPosition = isDuplicate && dupRow && (dupRow.Position || '') !== appliedPosition && appliedPosition !== '';

return [{
  json: {
    application_id: finalId,
    candidate_name: cls.candidate_name || '',
    candidate_email: email,
    phone: cls.phone || '',
    applied_position: appliedPosition,
    application_date: new Date().toISOString(),
    source: 'Gmail',
    is_duplicate: isDuplicate,
    different_position: differentPosition,
    previous_position: dupRow ? (dupRow.Position || '') : '',
    has_cv: hasCv,
    cv_type: cvType,
    email_subject: mail.subject || '',
    email_body: mail.text || '',
  },
  binary: outBinary,
}];

const item = $input.first().json || {};
const cvText = item.text || item.data || '';
return [{
  json: { cv_text: cvText },
  binary: $('Prepare Application').first().binary || {},
}];

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const req = rows[0] || {};
const found = !!(req['Job ID'] || req['Job title']);
return [{ json: {
  position_found: found,
  job_id: req['Job ID'] || '',
  job_title: req['Job title'] || '',
  required_skills: req['Required skills'] || '',
  preferred_skills: req['Preferred skills'] || '',
  min_experience: req['Minimum experience'] || 0,
  required_education: req['Required education'] || '',
  required_languages: req['Required languages'] || '',
  min_score: Number(req['Minimum score'] || 0),
  interview_duration: Number(req['Interview duration'] || 45),
  recruiter_email: req['Recruiter email'] || '',
} }];

