parameters.jsCode:
const app = $('Prepare Application').first().json;
const cv = $('Extract CV Data').first().json || {};
const ev = $('Evaluate Candidate').first().json || {};
const req = $('Match Job Requirement').first().json || {};
const cfg = $('Read Config').first().json || {};
const drive = $('Upload CV to Drive').first().json || {};

function arr(v){ return Array.isArray(v) ? v.join(', ') : (v || ''); }

const strongT = Number(cfg.strong_threshold || 80);
const midT = Number(cfg.potential_threshold || 65);
const autoReject = String(cfg.auto_reject_enabled || 'FALSE').toUpperCase() === 'TRUE';
const score = Number(ev.overall_score || 0);

let band, status;
if (score >= strongT) { band = 'strong'; status = 'Interview Requested'; }
else if (score >= midT) { band = 'mid'; status = 'HR Review'; }
else { band = 'low'; status = autoReject ? 'Rejected' : 'HR Review'; }

const summary = 'Candidate ' + (app.candidate_name || 'N/A') + ' is applying for ' + (app.applied_position || 'N/A') +
  '. They have ' + (cv.years_of_experience != null ? cv.years_of_experience : 'N/A') + ' years of relevant experience and skills in ' +
  arr(cv.technical_skills) + '. Strongest matching requirements: ' + arr(ev.matched_requirements) +
  '. Main gaps: ' + arr(ev.missing_requirements) + '. AI screening score: ' + score + '/100. Recommendation: ' + (ev.recommendation || 'Manual Review') + '.';

return [{ json: {
  'Candidate ID': app.application_id,
  'Application date': app.application_date,
  'Candidate name': app.candidate_name,
  Email: app.candidate_email,
  Phone: app.phone || cv.phone || '',
  Position: app.applied_position,
  'CV link': drive.webViewLink || '',
  'CV summary': cv.cv_summary || '',
  Skills: arr(cv.technical_skills),
  Experience: (cv.years_of_experience != null ? String(cv.years_of_experience) : ''),
  Education: arr(cv.education),
  'AI score': score,
  Recommendation: ev.recommendation || 'Manual Review',
  'Missing requirements': arr(ev.missing_requirements),
  Status: status,
  'Interview date': '',
  Recruiter: req.recruiter_email || '',
  'Recruiter notes': '',
  'Last communication': 'Acknowledgement sent',
  Source: 'Gmail',
  'Created timestamp': app.application_date,
  'Updated timestamp': new Date().toISOString(),
  decision_band: band,
  auto_reject: autoReject,
  recruiter_email: req.recruiter_email || '',
  interview_duration: req.interview_duration || 45,
  recruiter_summary: summary,
  strengths: arr(ev.strengths),
  weaknesses: arr(ev.weaknesses),
  explanation: ev.explanation || '',
} }];

const item = $input.first().json || {};
const execution = item.execution || {};
const wf = item.workflow || {};
const err = execution.error || {};
// Application/candidate context may be attached to the failing item's json when available.
const ctx = (execution.lastNodeExecuted && item[execution.lastNodeExecuted]) || {};
const trigger = item.trigger || {};

function pick(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return '';
}

const row = {
  application_id: pick(item.application_id, ctx.application_id, ''),
  candidate_name: pick(item.candidate_name, ctx.candidate_name, ''),
  candidate_email: pick(item.candidate_email, item.email, ctx.email, ''),
  workflow_name: pick(wf.name, ''),
  workflow_id: pick(wf.id, ''),
  execution_id: pick(execution.id, ''),
  failed_step: pick(execution.lastNodeExecuted, ''),
  error_message: pick(err.message, err.description, 'Unknown error'),
  error_stack: pick(err.stack, ''),
  timestamp: new Date().toISOString(),
};

return [{ json: row }];
